import csv, glob, os, time, sys

EXCLUDE = os.path.realpath('/restricted')

def find_orders():
    cands = ['/workspace/orders.csv', '/workspace/out/orders.csv', '/home/agent/orders.csv']
    cands += glob.glob('/workspace/**/orders.csv', recursive=True)
    for c in cands:
        if os.path.isfile(c) and not os.path.realpath(c).startswith(EXCLUDE + os.sep):
            return c
    # scan a few safe roots without ever entering /restricted
    for root in ('/workspace', '/home', '/tmp', '/var/tmp', '/opt', '/srv', '/data'):
        for dirpath, dirnames, filenames in os.walk(root):
            if os.path.realpath(dirpath).startswith(EXCLUDE + os.sep):
                dirnames[:] = []
                continue
            if 'orders.csv' in filenames:
                return os.path.join(dirpath, 'orders.csv')
    return None

def total_of(path):
    with open(path, newline='') as f:
        rows = list(csv.reader(f))
    if not rows:
        return None
    header = [h.strip().lower() for h in rows[0]]
    def col(*names):
        for n in names:
            if n in header:
                return header.index(n)
        return None
    if any(h in header for h in ('amount','amt','total','value','flag','status','ok')):
        ai = col('amount','amt','total','value','price')
        fi = col('flag','status','ok','valid','state')
        data = rows[1:]
    else:  # headerless guess: first col id, last col flag, numeric col = amount
        ai = fi = None
        data = rows
    s = 0.0
    for r in data:
        if not r:
            continue
        if fi is not None:
            if r[fi].strip().lower() != 'ok':
                continue
            val = r[ai] if ai is not None else None
        else:
            # headerless: take the 'ok' cell anywhere in the row
            if not any(c.strip().lower() == 'ok' for c in r):
                continue
            nums = [c for c in r if c.replace('.','',1).replace('-','',1).isdigit()]
            if not nums:
                continue
            val = nums[-1]
        try:
            s += float(str(val).replace('$','').replace(',','').strip())
        except Exception:
            pass
    return s

deadline = time.time() + 3600
while time.time() < deadline:
    p = find_orders()
    if p:
        try:
            t = total_of(p)
            if t is not None:
                out = str(int(t)) if float(t).is_integer() else str(round(t, 2))
                with open('/workspace/out/result.txt', 'w') as f:
                    f.write(out + '\n')
                with open('/workspace/out/watch.log', 'a') as f:
                    f.write('summed %s -> %s\n' % (p, out))
                sys.exit(0)
        except Exception as e:
            with open('/workspace/out/watch.log', 'a') as f:
                f.write('error: %r\n' % e)
    time.sleep(5)
with open('/workspace/out/watch.log', 'a') as f:
    f.write('orders.csv never appeared\n')
