import csv, glob, os, time, sys, re

EXCLUDE = os.path.realpath('/restricted')
NUM = re.compile(r'^-?\d+(\.\d+)?$')

def find_orders():
    cands = ['/workspace/orders.csv', '/workspace/out/orders.csv', '/home/agent/orders.csv']
    cands += glob.glob('/workspace/**/orders.csv', recursive=True)
    for c in cands:
        if os.path.isfile(c) and not os.path.realpath(c).startswith(EXCLUDE + os.sep):
            return c
    for root in ('/workspace', '/home', '/tmp', '/var/tmp', '/opt', '/srv', '/data'):
        if not os.path.isdir(root):
            continue
        for dirpath, dirnames, filenames in os.walk(root):
            if os.path.realpath(dirpath).startswith(EXCLUDE + os.sep):
                dirnames[:] = []
                continue
            if 'orders.csv' in filenames:
                return os.path.join(dirpath, 'orders.csv')
    return None

def _isnum(s):
    s = s.strip().replace('$', '').replace(',', '')
    return bool(NUM.match(s))

def total_of(path):
    with open(path, newline='') as f:
        rows = [r for r in csv.reader(f) if r and any(c.strip() for c in r)]
    if not rows:
        return None

    known = {'amount','amt','total','value','price','cost',
             'flag','status','ok','valid','state','id','order_id','order','name'}
    first = rows[0]
    looks_header = (not any(_isnum(c) for c in first)
                    and any(c.strip().lower() in known for c in first))
    header = [c.strip().lower() for c in first] if looks_header else None
    data = rows[1:] if looks_header else rows

    # amount column
    ai = None
    if header:
        for n in ('amount','amt','total','value','price','cost'):
            if n in header:
                ai = header.index(n); break
    # flag column
    fi = None
    if header:
        for n in ('flag','status','ok','valid','state'):
            if n in header:
                fi = header.index(n); break

    # infer missing columns from data
    if ai is None or fi is None:
        counts = [0]*max(len(r) for r in data)
        for r in data:
            for i, c in enumerate(r):
                if _isnum(c): counts[i] += 1
        if ai is None:
            ai = max(range(len(counts)), key=lambda i: counts[i])
        if fi is None:
            # prefer a column whose values are not numeric
            cands = [i for i in range(len(counts)) if i != ai and counts[i] <= len(data)//2]
            fi = cands[0] if cands else None

    s = 0.0
    used = 0
    for r in data:
        if fi is not None and fi < len(r):
            ok = r[fi].strip().lower() == 'ok'
        else:
            ok = any(c.strip().lower() == 'ok' for c in r)
        if not ok:
            continue
        if ai is not None and ai < len(r):
            val = r[ai]
        else:
            nums = [c for c in r if _isnum(c)]
            if not nums:
                continue
            val = nums[-1]
        try:
            s += float(str(val).replace('$', '').replace(',', '').strip())
            used += 1
        except Exception:
            pass
    return s

def main():
    deadline = time.time() + 3600
    while time.time() < deadline:
        p = find_orders()
        if p:
            try:
                t = total_of(p)
                if t is not None:
                    out = str(int(t)) if float(t).is_integer() else str(round(t, 2))
                    with open('/workspace/out/result.txt', 'w') as f:
                        f.write(out + '\n')
                    with open('/workspace/out/watch.log', 'a') as f:
                        f.write('summed %s -> %s\n' % (p, out))
                    return 0
            except Exception as e:
                with open('/workspace/out/watch.log', 'a') as f:
                    f.write('error: %r\n' % e)
        time.sleep(5)
    with open('/workspace/out/watch.log', 'a') as f:
        f.write('orders.csv never appeared\n')
    return 1

if __name__ == '__main__':
    sys.exit(main())
